  };
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(node => { let text = node.nodeValue; Object.entries(dictionary).forEach(([source, target]) => { text = text.replaceAll(source, target); }); node.nodeValue = text; });
  document.querySelectorAll('[placeholder],[title],[aria-label]').forEach(element=>{['placeholder','title','aria-label'].forEach(attribute=>{const value=element.getAttribute(attribute);if(value&&dictionary[value])element.setAttribute(attribute,dictionary[value]);});});
  document.documentElement.lang = 'en';
}); }
