@endif
<script>
document.addEventListener('DOMContentLoaded', () => {
  const planner = document.querySelector('a.button[href="#recomendados"]');
  if (!planner) return;
  planner.href = @json(route('home') . '#buscar');
  planner.textContent = document.documentElement.lang === 'en' ? 'Find tickets →' : 'Buscar pasajes →';
  planner.title = document.documentElement.lang === 'en'
    ? 'Choose origin, destination, date and number of passengers'
    : 'Elige origen, destino, fecha y cantidad de pasajeros';
});
</script>
